import { createHash } from "node:crypto";

type Flag = { key: string; enabled: boolean; rolloutPercent: number };

// 0..99, same result for the same flag + user, on every server
function bucket(flagKey: string, userId: string): number {
  const hash = createHash("sha256").update(`${flagKey}:${userId}`).digest();
  return hash.readUInt32BE(0) % 100;
}

export function isEnabled(flag: Flag | undefined, userId: string): boolean {
  if (!flag || !flag.enabled) return false; // safe default: old behaviour
  return bucket(flag.key, userId) < flag.rolloutPercent;
}

