const flags = OpenFeature.getClient();

export async function priceFor(userId: string, cart: Cart) {
  const useNew = await flags.getBooleanValue("new-pricing", true, {
    targetingKey: userId,
  });
  return useNew ? newPricing(cart) : oldPricing(cart);
}

