import { z } from "zod";

const Env = z.object({
  NODE_ENV: z.enum(["development", "test", "production"]),
  PORT: z.coerce.number().int().min(1).max(65535).default(3000), // "" coerces to 0
  DATABASE_URL: z.string().startsWith("postgres"),
  PAYMENT_API_KEY: z.string().min(20),
  SIGNUPS_ENABLED: z
    .enum(["true", "false"])
    .default("true")
    .transform((v) => v === "true"),
});

const parsed = Env.safeParse(process.env);
if (!parsed.success) {
  for (const issue of parsed.error.issues) {
    console.error(`Invalid env ${issue.path.join(".")}: ${issue.message}`);
  }
  process.exit(1); // fail the deploy, not the first customer
}

export const config = parsed.data;

export const config = {
  port: Number(process.env.PORT) || 3000,
  databaseUrl: process.env.DATABASE_URL ?? "postgres://localhost:5432/dev",
  paymentApiKey: process.env.PAYMENT_API_KEY || "sk_test_local_123",
  paymentApiUrl: process.env.PAYMENT_API_URL || "https://sandbox.pay.example",
};

import { createHmac, timingSafeEqual } from "node:crypto";

// During rotation: WEBHOOK_SECRETS="new_secret,old_secret". After the window: "new_secret".
const secrets = (process.env.WEBHOOK_SECRETS ?? "")
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);
if (secrets.length === 0) throw new Error("WEBHOOK_SECRETS is not set");

export function isValidSignature(rawBody: string, signatureHex: string): boolean {
  const received = Buffer.from(signatureHex, "hex");
  return secrets.some((secret) => {
    const expected = createHmac("sha256", secret).update(rawBody).digest();
    return expected.length === received.length && timingSafeEqual(expected, received);
  });
}

